(() => {
  'use strict';
  const D=JSON.parse(document.getElementById('nfl-data').textContent), S=D.scores, C=NFLCatchUp;
  const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmt=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'America/New_York'});
  const teamMap=Object.fromEntries(S.teams.map(t=>[t.id,t]));
  const team=id=>teamMap[id], full=id=>team(id)?.name||id, short=id=>team(id)?.short||id;
  const names={brief:'CATCH UP',games:'ALL GAMES',teams:'TEAM ROOMS',league:'STANDINGS',learn:'NEW TO FOOTBALL'};
  const topics={all:'All stories',games:'Game stories',roster:'Roster moves',injuries:'Injuries'};
  const KEY='dfe-nfl-huddle-v1'; let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}');}catch{}
  let linked={};try{if(location.hash.startsWith('#catchup=')){linked=JSON.parse(decodeURIComponent(location.hash.slice(9)));linked.spoilers=true;}}catch{}
  let state=C.normalize({...saved,...linked},S), revealed=new Set(), storyLimit=6, gameLimit=48, toastTimer, openedGame=null;
  const current=C.records(S), recordMap=Object.fromEntries(current.map(r=>[r.id,r]));
  const completed=S.games.filter(g=>g.completed), remaining=S.games.filter(g=>!g.completed);
  function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{}}
  function notice(s){$('#toast').textContent=s;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent='',3500);}
  function safeLink(url){try{const u=new URL(url);return u.protocol==='https:'?esc(u.href):'#';}catch{return '#';}}
  function locked(id){return state.spoilers&&!revealed.has(id);}
  function badge(id,size='normal'){
    const t=team(id); if(!t)return '';
    return `<span class="team-badge ${size}"><span aria-hidden="true">${esc(id)}</span>${t.logo?`<img src="${safeLink(t.logo)}" alt="" loading="lazy" decoding="async" onload="this.parentElement.classList.add('loaded')" onerror="this.remove()">`:''}</span>`;
  }
  function setState(changes,{keepLimit=false,focus=false}={}){
    state=C.normalize({...state,...changes},S);if(!keepLimit){storyLimit=state.depth==='little'?3:6;gameLimit=48;}
    persist();render();if(focus){$('#view').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
  }
  function when(g,compact=false){
    if(!g.time_confirmed&&!g.completed)return `Week ${g.week} · Kickoff TBD`;
    if(g.completed)return `${fmt(C.localDate(g.date))} · ${locked(g.id)?'Final':g.status}`;
    return new Date(g.date).toLocaleString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric',...(compact?{}:{hour:'numeric',minute:'2-digit'})})+(compact?'':' ET');
  }
  function seasonTimeline(active=state.week){
    return `<div class="season-timeline"><div class="timeline-heading"><span class="eyebrow">YOUR SEASON MAP</span><span>18 weeks <i>/</i> 272 games</span></div><div class="week-rail" role="group" aria-label="Season weeks"><button data-week="all" class="all-weeks ${active==='all'?'active':''}" aria-pressed="${active==='all'}">ALL<span>272</span></button>${Array.from({length:18},(_,i)=>{const w=i+1,n=S.games.filter(g=>g.week===w).length;return `<button data-week="${w}" class="${w<=S.through_week?'played':'future'} ${active===w?'active':''}" aria-pressed="${active===w}" aria-label="Week ${w}, ${n} games${w<=S.through_week?', completed':''}"><span>WK</span>${String(w).padStart(2,'0')}<i></i></button>`;}).join('')}</div><div class="timeline-legend"><span><i class="played-dot"></i> Weeks 1–${S.through_week} complete; Week ${S.latest_week||S.through_week} finals included</span><span><i></i> Upcoming · unconfirmed times marked TBD</span></div></div>`;
  }
  function scoreStrip(){
    const games=S.games.filter(g=>g.week===(S.latest_week||S.through_week)&&g.completed&&(state.team==='ALL'||[g.home.team,g.away.team].includes(state.team)));
    $('#score-strip').innerHTML=`<div class="strip-label"><span>THE LAST<br>WHISTLE</span><small>WEEK ${S.latest_week||S.through_week}</small></div><div class="score-scroll">${games.map(g=>`<button class="strip-game" data-game="${g.id}" aria-label="Open ${esc(full(g.away.team))} at ${esc(full(g.home.team))}"><span class="strip-status">${locked(g.id)?'FINAL · HIDDEN':esc(g.status)}</span><span>${badge(g.away.team,'mini')}<b>${g.away.team}</b><strong>${locked(g.id)?'—':g.away.score}</strong></span><span>${badge(g.home.team,'mini')}<b>${g.home.team}</b><strong>${locked(g.id)?'—':g.home.score}</strong></span></button>`).join('')||'<p class="no-strip">A bye week here. The full season is one click away.</p>'}</div><button class="strip-all" data-tab="games">All games <span>↗</span></button>`;
  }
  function featuredGame(){return [...completed].reverse().find(g=>state.team==='ALL'||[g.away.team,g.home.team].includes(state.team))||completed[completed.length-1];}
  function feature(g){
    const hide=locked(g.id),read=C.gameRead(g);
    return `<article class="feature-game"><div class="feature-top"><span class="eyebrow">${state.team==='ALL'?'LAST GAME IN THE BOOKS':'YOUR TEAM’S LATEST GAME'}</span><span class="status-pill">${hide?'OUTCOME HIDDEN':esc(read.kind)}</span></div><div class="feature-match"><div>${badge(g.away.team,'giant')}<h3>${esc(short(g.away.team))}</h3><span>AWAY</span></div><div class="feature-score"><strong>${hide?'—':g.away.score}<i>:</i>${hide?'—':g.home.score}</strong><span>${fmt(C.localDate(g.date))} / WEEK ${g.week}</span></div><div>${badge(g.home.team,'giant')}<h3>${esc(short(g.home.team))}</h3><span>${g.neutral?'DESIGNATED HOME':'HOME'}</span></div></div><div class="feature-bottom"><span>${hide?'Ready when you are.':esc(read.text)}</span><button class="round-button" data-game="${g.id}" aria-label="Open featured game">↗</button></div></article>`;
  }
  function resultCard(g,compact=false){
    const hide=g.completed&&locked(g.id),read=C.gameRead(g),rows=[g.away,g.home];
    return `<article class="game-card ${g.completed?'final-game':'scheduled-game'}"><div class="game-card-top"><span>W${String(g.week).padStart(2,'0')} <i>·</i> ${esc(when(g,true))}</span>${g.completed&&!hide?`<span class="game-tag">${esc(read.kind)}</span>`:!g.completed?'<span class="scheduled-dot"></span>':''}</div><button class="game-open" data-game="${g.id}" aria-label="Open ${esc(full(g.away.team))} at ${esc(full(g.home.team))}, week ${g.week}">${rows.map((r,i)=>`<span class="game-team ${g.completed&&!hide&&r.score>rows[1-i].score?'winner':''}">${badge(r.team)}<span><strong>${esc(short(r.team))}</strong><small>${esc(team(r.team).location)}${i?' · '+(g.neutral?'neutral':'home'):''}</small></span><b>${g.completed?(hide?'—':r.score):'—'}</b></span>`).join('')}</button><div class="game-card-bottom"><span>${hide?'Scores protected':g.completed?`${Math.abs(g.home.score-g.away.score)}-point margin`:esc(g.broadcasts?.join(' / ')||'Broadcast TBD')}</span><button class="text-button" data-game="${g.id}">${g.completed?'Inside the game':'Matchup preview'} ↗</button></div>${compact?'':`<p class="venue">${esc(g.venue)}</p>`}</article>`;
  }
  function storiesMarkup(ss){return ss.slice(0,storyLimit).map((s,i)=>{
    const hide=s.spoiler&&locked(s.id);
    return `<article class="story" id="story-${s.id}"><div class="story-side"><span>${String(i+1).padStart(2,'0')}</span><div>${s.teams.map(t=>badge(t,'small')).join('')}</div></div><div class="story-main"><div class="story-meta"><span class="story-category ${s.category}">${topics[s.category]}</span><time>${fmt(s.date)}</time></div><h3>${esc(hide?s.safe_title:s.title)}</h3>${hide?`<p>A sourced game story is ready. Reveal it when you’re ready for the result.</p><button class="secondary-button" data-reveal="${s.id}">Reveal this story</button>`:`<p>${esc(s.summary)}</p>${state.depth==='little'?`<div class="explanation"><b>THE FOOTBALL PART</b><p>${esc(s.context)}</p></div>`:''}<div class="change-pair"><div><span>THEN</span><p>${esc(s.before)}</p></div><span class="change-arrow">→</span><div><span>AT THE TIME</span><p>${esc(s.after)}</p></div></div><details ${state.depth==='well'?'open':''}><summary>More context & the source</summary><p>${esc(s.detail)}</p><div class="explanation"><b>OUR CONTEXT</b><p>${esc(s.meaning)}</p></div><a href="${safeLink(s.source)}" target="_blank" rel="noopener noreferrer">${esc(s.publisher)} ↗</a>${s.secondary_source?` <a href="${safeLink(s.secondary_source)}" target="_blank" rel="noopener noreferrer">Supporting report ↗</a>`:''}<small>Event ${fmt(s.date)} · Published ${fmt(s.published)} · Reviewed ${fmt(D.reviewed_at)}, 2026</small></details>`}</div></article>`;
  }).join('');}
  function formDots(row,limit=5){return `<div class="form-dots" aria-label="Most recent results, oldest to newest">${row.form.slice(-limit).map(f=>`<span class="${f.outcome.toLowerCase()}" title="Week ${f.week}: ${f.outcome}">${f.outcome}</span>`).join('')}</div>`;}
  function movement(){
    if(state.spoilers)return `<div class="protected-panel"><span>◉</span><h3>Records can give the game away.</h3><p>Team form and results stay hidden while outcome protection is on.</p><button class="secondary-button" data-show-outcomes>Show outcomes</button></div>`;
    const before=C.records(S,state.since),oldMap=Object.fromEntries(before.map(r=>[r.id,r]));
    let rows=current.filter(r=>(state.team==='ALL'||r.id===state.team)&&r.gp>oldMap[r.id].gp);
    rows.sort((a,b)=>(b.w-oldMap[b.id].w)-(a.w-oldMap[a.id].w)||b.pct-a.pct||a.name.localeCompare(b.name));
    return `<div class="movement-list">${rows.slice(0,4).map(r=>`<button class="mover" data-team-room="${r.id}">${badge(r.id)}<span><b>${esc(r.short)}</b><small>${r.w-oldMap[r.id].w}W · ${r.l-oldMap[r.id].l}L${r.t-oldMap[r.id].t?' · '+(r.t-oldMap[r.id].t)+'T':''} in your window</small></span><strong><small>${C.record(oldMap[r.id])} → </small>${C.record(r)}</strong><i>↗</i></button>`).join('')||'<p class="subtle">No completed games in this date window.</p>'}</div><p class="microcopy">${state.team==='ALL'?'Most wins in your window; ties use season win percentage, then name. ':''}Tap a team to see its full season.</p>`;
  }
  function brief(){
    const ss=C.stories(D,state),gs=C.games(S,state),fg=featuredGame();
    return `<section class="home-hero"><div class="hero-copy"><span class="eyebrow"><i class="accent-dot"></i> YOUR 2026 NFL RE-ENTRY POINT</span><h1><span>THE SEASON.</span><br><em>IN FOCUS.</em></h1><p>${state.team==='ALL'?'Every matchup. The stories you missed.<br>Exactly as much context as you need.':`Your way back into the ${esc(short(state.team))} season.<br>Every result, the next matchup, and what changed.`}</p><button class="primary-button" data-all-games>Explore all 272 games <span>↗</span></button><div class="hero-statline"><span><b>${completed.length}</b> FINAL</span><span><b>${remaining.length}</b> UPCOMING</span><span><b>32</b> TEAMS</span></div></div>${feature(fg)}</section>${seasonTimeline(S.latest_week||S.through_week)}${state.team!=='ALL'?teamBriefing(state.team)+teamReporting(state.team):recentReporting()}
    <div class="dashboard-grid"><section class="story-section"><div class="section-heading"><div><span class="eyebrow">SINCE ${fmt(state.since).toUpperCase()}</span><h2>Selected story context.</h2></div><span class="count-label">${ss.length} STORIES</span></div><div class="story-filters"><div class="chip-row">${Object.entries(topics).map(([id,n])=>`<button data-topic="${id}" class="chip ${state.topic===id?'active':''}" aria-pressed="${state.topic===id}">${n}</button>`).join('')}</div><div class="search-row"><label class="search-box"><span>⌕</span><input id="search" type="search" placeholder="Search stories or players" aria-label="Search stories" value="${esc(state.query)}"></label><select id="order" aria-label="Sort stories"><option value="impact" ${state.order==='impact'?'selected':''}>Big picture</option><option value="latest" ${state.order==='latest'?'selected':''}>Latest</option></select></div></div><div class="story-feed">${ss.length?storiesMarkup(ss):`<div class="empty"><h3>No stories in this view.</h3><p>${gs.length} game results match your team and date. Reviewed stories are selective; try a broader filter or open all games.</p><button class="secondary-button" data-reset-filters>Broaden filters</button></div>`}</div>${ss.length>storyLimit?`<button class="load-more" id="more">Show ${ss.length-storyLimit} more stories <span>+</span></button>`:''}<p class="microcopy">Selected reporting, reviewed ${fmt(D.reviewed_at)}. Every game is available in the game explorer.</p></section>
    <aside class="right-column"><section class="panel"><div class="section-heading small"><h2>The movement.</h2><span>↗</span></div><p class="subtle">Records before and after your time away.</p>${movement()}</section><section class="next-panel"><span class="eyebrow">ON THE HORIZON</span><h2>The next whistle.</h2>${nextGame()}</section><section class="awareness-note"><span class="orb">◎</span><h3>${{little:'You don’t need to know the jargon.',basics:'You know the game. Fill in the gaps.',well:'Follow the numbers a little further.'}[state.depth]}</h3><p>${{little:'Game panels explain scoring, the numbers, and what changed. The basics are always a tap away.',basics:'Before-and-after records and quarter scores connect each result to the bigger season.',well:'Game panels include the full available stat comparison, player leaders and quarter-by-quarter scoring.'}[state.depth]}</p><button class="text-button" data-tab="learn">Football, explained ↗</button></section></aside></div>
    <section class="recent-section"><div class="section-heading"><div><span class="eyebrow">THE GAMES BEHIND THE STORIES</span><h2>Your window, on the field.</h2></div><button class="text-button" data-window-games>Open game explorer ↗</button></div><p class="subtle">${gs.length} completed games since ${fmt(state.since)}${state.team==='ALL'?'':` involving ${esc(full(state.team))}`}. Showing the latest six.</p><div class="games-grid">${[...gs].reverse().slice(0,6).map(g=>resultCard(g,true)).join('')||'<div class="empty">No games in this date window. The full schedule is still available.</div>'}</div></section>`;
  }
  function nextGame(){
    const g=remaining.find(g=>state.team==='ALL'||[g.home.team,g.away.team].includes(state.team));
    if(!g)return '<p>No upcoming game remains in the regular-season schedule.</p>';
    return `<div class="next-match">${badge(g.away.team,'large')}<span>AT</span>${badge(g.home.team,'large')}</div><h3>${esc(short(g.away.team))} <span>at</span> ${esc(short(g.home.team))}</h3><p>${esc(when(g))}</p><small>${esc(g.venue)}</small><button class="secondary-button" data-game="${g.id}">Open matchup ↗</button>`;
  }
  function gamesView(){
    const filtered=C.schedule(S,state),shown=filtered.slice(0,gameLimit),groups=[...new Set(shown.map(g=>g.week))];
    return `<div class="page-title"><div><span class="eyebrow">NO MISSING WEEKS</span><h1>ALL THE <em>GAMES.</em></h1><p>Every regular-season matchup, from the opening kickoff to Week 18.</p></div><div class="big-total"><b>272</b><span>GAMES / 18 WEEKS</span></div></div>${seasonTimeline()}
    <div class="game-toolbar"><div class="chip-row" role="group" aria-label="Game status">${[['all','All games'],['final','Completed'],['scheduled','Upcoming']].map(([id,n])=>`<button class="chip ${state.gameStatus===id?'active':''}" data-status="${id}" aria-pressed="${state.gameStatus===id}">${n}</button>`).join('')}</div><label class="search-box"><span>⌕</span><input id="game-search" type="search" placeholder="Team or stadium" aria-label="Search games" value="${esc(state.gameQuery)}"></label><label class="close-filter"><input id="close-games" type="checkbox" ${state.closeGames?'checked':''} ${state.spoilers?'disabled':''}> Within 7 points</label></div>
    <div class="results-meta"><span><b>${filtered.length}</b> matching games ${state.team==='ALL'?'':`/ ${esc(full(state.team))}`}</span><span>${state.spoilers?'Outcomes protected · close-finish filter disabled':'Open any matchup for the details'} · Eastern Time</span></div>
    ${filtered.length?groups.map(w=>`<section class="week-group"><div class="week-group-title"><h2>WEEK <span>${String(w).padStart(2,'0')}</span></h2><span>${w<=S.through_week?'IN THE BOOKS':w===S.latest_week?'PARTLY COMPLETE':'STILL TO COME'}</span></div><div class="games-grid">${shown.filter(g=>g.week===w).map(g=>resultCard(g)).join('')}</div></section>`).join(''):`<div class="empty"><h3>No games match these filters.</h3><p>A team may be on its bye, or your selected week may not have completed or upcoming games.</p><button class="secondary-button" data-clear-game-filters>Show the full schedule</button></div>`}
    ${filtered.length>shown.length?`<button id="more-games" class="load-more">Load the next ${Math.min(48,filtered.length-shown.length)} games <span>${shown.length} / ${filtered.length}</span></button>`:''}<p class="microcopy">The week selector replaces your catch-up date filter here. This is the 272-game regular season; future postseason matchups are not yet determined. Schedule checked ${fmt(S.as_of)}, 2026.</p>`;
  }
  function progressChart(row){
    if(state.spoilers)return '<div class="chart-hidden">Season progression hidden with outcomes.</div>';
    const pts=[{w:0,n:0}],data=row.form;let wins=0;data.forEach(f=>{if(f.outcome==='W')wins++;pts.push({w:f.week,n:wins});});
    const W=500,H=170,pad=25,x=w=>pad+w/18*(W-pad*2),y=n=>H-pad-n/Math.max(8,row.w+1)*(H-pad*2);
    return `<svg class="progress-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(row.name)} cumulative wins: ${row.w} through ${row.gp} games"><g class="chart-grid">${[0,2,4,6,8].map(n=>`<path d="M${pad} ${y(n)}H${W-pad}"/><text x="8" y="${y(n)+3}">${n}</text>`).join('')}</g><path class="chart-future" d="M${x(S.through_week)} 15V${H-pad}"/><polyline class="chart-line" points="${pts.map(p=>`${x(p.w)},${y(p.n)}`).join(' ')}"/>${pts.map(p=>`<circle cx="${x(p.w)}" cy="${y(p.n)}" r="3"/>`).join('')}<g class="chart-labels">${[1,4,8,12,18].map(w=>`<text x="${x(w)}" y="${H-5}" text-anchor="middle">W${w}</text>`).join('')}</g></svg><p class="microcopy">Cumulative wins by week. Dashed line = last fully completed week. Finals from the current week are included.</p>`;
  }
  function teamRoom(){
    const id=state.teamFocus,row=recordMap[id],games=S.games.filter(g=>[g.home.team,g.away.team].includes(id)),related=D.stories.filter(s=>s.teams.includes(id));
    const next=games.find(g=>!g.completed),last=games.filter(g=>g.completed).slice(-1)[0];
    return `<div class="page-title"><div><span class="eyebrow">PICK A SIDE. SEE THE WHOLE STORY.</span><h1>TEAM <em>ROOMS.</em></h1><p>One team, all 17 games, and its path through the season.</p></div><label class="room-select">YOUR TEAM ROOM<select id="team-focus">${S.teams.map(t=>`<option value="${t.id}" ${t.id===id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label></div><div class="team-roster" role="group" aria-label="Choose a team">${S.teams.map(t=>`<button data-team-room="${t.id}" class="${t.id===id?'active':''}" aria-pressed="${t.id===id}" title="${esc(t.name)}" aria-label="${esc(t.name)}">${badge(t.id,'small')}<span>${t.id}</span></button>`).join('')}</div>
    <section class="team-room-hero"><div class="room-identity">${badge(id,'giant')}<div><span class="eyebrow">${row.division}</span><h2>${esc(row.location)}<strong>${esc(row.short)}</strong></h2><button class="text-button" data-follow-team="${id}">${state.team===id?'Following in your catch up ✓':'Follow in my catch up ↗'}</button></div></div><div class="room-record"><strong>${state.spoilers?'—':C.record(row)}</strong><span>${state.spoilers?'OUTCOMES HIDDEN':'REGULAR-SEASON RECORD'}</span>${state.spoilers?'':formDots(row,8)}</div><div class="room-stats"><span><b>${state.spoilers?'—':(row.pf/row.gp).toFixed(1)}</b>POINTS / GAME</span><span><b>${state.spoilers?'—':(row.pa/row.gp).toFixed(1)}</b>ALLOWED / GAME</span><span><b>${17-row.gp}</b>GAMES TO GO</span></div></section>
    ${teamBriefing(id)}<div class="team-room-grid"><section class="panel"><div class="section-heading small"><h2>The season’s shape.</h2><span class="eyebrow">CUMULATIVE WINS</span></div>${progressChart(row)}</section><section class="panel compact-match"><div class="section-heading small"><h2>Next up.</h2></div>${next?`<div class="compact-match-row">${badge(next.away.team,'large')}<strong>${next.away.team}<span>at</span>${next.home.team}</strong>${badge(next.home.team,'large')}</div><p class="subtle">${esc(when(next))}</p><button class="secondary-button" data-game="${next.id}">Matchup details ↗</button>`:'<p>Regular-season schedule complete.</p>'}</section></div>
    <div class="section-heading"><div><span class="eyebrow">ALL 18 WEEKS, INCLUDING THE BYE</span><h2>The whole road.</h2></div><span class="count-label">17 GAMES</span></div><div class="team-schedule">${Array.from({length:18},(_,i)=>{const w=i+1,g=games.find(g=>g.week===w);if(!g)return `<div class="schedule-stop bye"><span>W${String(w).padStart(2,'0')}</span><b>BYE</b><small>Week off</small></div>`;const own=g.home.team===id?g.home:g.away,opp=own===g.home?g.away:g.home,hide=locked(g.id),result=own.score>opp.score?'W':own.score<opp.score?'L':'T';return `<button data-game="${g.id}" class="schedule-stop ${g.completed&&!hide?result.toLowerCase():'pending'}"><span>W${String(w).padStart(2,'0')}</span>${badge(opp.team,'small')}<b>${own===g.away?'@ ':''}${opp.team}</b><small>${g.completed?(hide?'Final · hidden':`${result} ${own.score}–${opp.score}`):g.time_confirmed?fmt(C.localDate(g.date)):'Date / time TBD'}</small></button>`;}).join('')}</div>
    ${teamReporting(id)}<div class="section-heading"><h2>Selected deeper reads.</h2><span class="count-label">${related.length} SOURCED STORIES</span></div><div class="story-feed room-stories">${related.length?storiesMarkup(related):'<div class="empty"><h3>The games are here. The reporting is selective.</h3><p>No reviewed editorial story is included for this team yet. All of its regular-season matchups are above.</p></div>'}</div>`;
  }
  function teamBriefing(id){
    const b=C.teamBrief(S,id,state.since),n=b.window.length;
    if(state.spoilers)return `<section class="team-briefing panel"><span class="eyebrow">WHAT YOU MISSED / ${esc(short(id))}</span><h2>Your team’s story is ready.</h2><p>Form, offensive production, defense and player performances can reveal results.</p><button class="secondary-button" data-show-outcomes>Show the team briefing</button></section>`;
    const num=x=>x?x.value.toFixed(1):'unavailable';
    const trajectory=n?`${short(id)} went ${b.delta.w}–${b.delta.l}${b.delta.t?'–'+b.delta.t:''} since ${fmt(state.since)}, moving from ${C.record(b.before)} to ${C.record(b.now)}.`:`No completed ${short(id)} game falls in this window. Their season record is ${C.record(b.now)}.`;
    return `<section class="team-briefing"><div class="section-heading"><div><span class="eyebrow">WHAT YOU MISSED / SINCE ${fmt(state.since).toUpperCase()}</span><h2>The ${esc(short(id))} story.</h2></div><span class="count-label">${n} GAMES IN YOUR WINDOW</span></div><p class="briefing-lead">${esc(trajectory)}</p><div class="facet-grid"><article class="facet"><span class="eyebrow">01 / THE LATEST CHAPTER</span><h3>${n?esc(C.gameRead(b.window.at(-1)).kind):'A quieter window'}</h3><p>${n?esc(C.gameRead(b.window.at(-1)).text):'Widen your starting date to connect more games.'}</p>${b.latest?`<button class="text-button" data-game="${b.latest.id}">Latest game evidence ↗</button>`:''}</article><article class="facet"><span class="eyebrow">02 / THE OFFENSE</span><h3>${n?num(b.points)+' points per game':'Waiting for a game'}</h3><p>${n?`${num(b.yards)} total yards per game: ${num(b.pass)} net passing and ${num(b.rush)} rushing. Season scoring average: ${num(b.seasonPoints)}.`:'No offense averages for this date window.'}</p><small>Window averages · ${b.yards?.n||0} available yardage box scores</small></article><article class="facet"><span class="eyebrow">03 / DEFENSE & POSSESSION</span><h3>${n?num(b.allowed)+' points allowed per game':'No results in this window'}</h3><p>${n?`${num(b.conceded)} opponent yards per game. ${num(b.takeaways)} takeaways versus ${num(b.turnovers)} giveaways per game.`:'Defensive production appears after completed games.'}</p><small>Points allowed are team totals, including non-offensive scores.</small></article><article class="facet"><span class="eyebrow">04 / THE QUARTERBACK</span><h3>${esc(b.passer?.name||'No passing leader available')}</h3><p>${b.passer?esc(b.passer.stat):'Open individual box scores for available player production.'}</p><small>${b.latest?'Latest final: '+fmt(C.localDate(b.latest.date))+'. ':''}Passing leader, not confirmation of the next starter.</small></article></div>${state.depth==='little'?'<div class="explanation"><b>CONNECTING THE DOTS</b><p>Points decide games. Yards describe movement. A takeaway gives your team the ball; a giveaway hands it to the opponent. These numbers describe what happened, but do not establish why a coach or player made a decision.</p></div>':''}<p class="microcopy">Calculated from ESPN game results and available box scores. Full season: ${b.all.length} completed games. News and roster changes below are dated separately.</p><button class="text-button" data-research-team="${id}">Ask a question about ${esc(short(id))} ↗</button></section>`;
  }
  function recentReporting(){
    if(state.spoilers)return '';
    const unique=new Map();
    for(const [id,t] of Object.entries(D.reporting.teams)){for(const a of t.news){if(a.date<state.since)continue;const found=unique.get(a.id);if(found)found.teams.push(id);else unique.set(a.id,{...a,teams:[id]});}}
    const items=[...unique.values()].sort((a,b)=>b.published.localeCompare(a.published)).slice(0,6);
    return `<section class="team-reporting"><div class="section-heading"><div><span class="eyebrow">REPORTING CHECKED ${fmt(D.reporting.as_of).toUpperCase()}</span><h2>Around the NFL.</h2></div><button class="text-button" data-tab="teams">All 32 team briefings ↗</button></div><p class="subtle">The latest collected headlines. Open a team room for its full context, injury reporting, coaching news and official roster moves.</p><div class="reporting-facets">${items.map(a=>`<article class="facet"><span class="eyebrow">${fmt(a.date)} / ${esc(a.category)}</span><a class="report-link" href="${safeLink(a.source)}" target="_blank" rel="noopener noreferrer"><strong>${esc(a.title)} ↗</strong><small>ESPN · reported headline</small></a>${a.teams.map(id=>`<button class="text-button" data-team-room="${id}">${id} team room ↗</button>`).join(' · ')}</article>`).join('')||'<p>No collected headlines in this date window.</p>'}</div></section>`;
  }
  function teamReporting(id){
    const r=D.reporting?.teams[id];if(!r)return '<p class="empty">Reporting coverage is not available for this team.</p>';
    if(state.spoilers)return `<section class="panel"><h2>Off the field, too.</h2><p>Reporting can mention results. Turn off outcome protection to open this team’s dated news and transactions.</p><button class="text-button" data-show-outcomes>Show reporting ↗</button></section>`;
    const news=r.news.filter(x=>x.date>=state.since),moves=r.transactions.filter(x=>x.date>=state.since);
    const facets=['Quarterback','Health','Coaching','Roster','Around the team'];
    return `<section class="team-reporting"><div class="section-heading"><div><span class="eyebrow">THE PEOPLE BEHIND THE RECORD</span><h2>Beyond the scoreboard.</h2></div><span class="count-label">CHECKED ${fmt(D.reporting.as_of).toUpperCase()}</span></div><p class="subtle">Dated reports since ${fmt(state.since)}. Headlines are links to reporting, not independently confirmed roster facts. An old injury report does not tell you who can play today.</p><div class="reporting-facets">${facets.map(f=>{const items=news.filter(x=>x.category===f);return `<details class="reporting-facet" ${items.length?'open':''}><summary><span>${f}</span><b>${items.length} ${items.length===1?'report':'reports'}</b></summary>${items.length?items.map(x=>`<a class="report-link" href="${safeLink(x.source)}" target="_blank" rel="noopener noreferrer"><time>${fmt(x.date)}</time><strong>${esc(x.title)} ↗</strong><small>ESPN · reported headline</small></a>`).join(''):`<p class="coverage-gap">No matching report in this collected feed and date window. This is a coverage gap, not confirmation that nothing changed.</p>`}</details>`;}).join('')}</div><details class="transaction-log" open><summary>Official roster transaction log <span>${moves.length} entries in your window</span></summary>${r.transactions_status==='available'?`<ol>${moves.slice(0,12).map(x=>`<li><time>${fmt(x.date)}</time><p>${esc(x.text)}</p></li>`).join('')||'<li>No listed transaction in this window.</li>'}</ol>${moves.length>12?`<details><summary>Show ${moves.length-12} earlier entries</summary><ol>${moves.slice(12).map(x=>`<li><time>${fmt(x.date)}</time><p>${esc(x.text)}</p></li>`).join('')}</ol></details>`:''}`:'<p class="coverage-gap">The official log could not be collected. Open the team’s site for roster news; no absence of activity is implied.</p>'}<a class="text-button" href="${safeLink(r.transactions_status==='available'?r.transactions_source:r.official_news)}" target="_blank" rel="noopener noreferrer">Official team ${r.transactions_status==='available'?'transaction log':'news'} ↗</a></details><p class="microcopy">Recent feed coverage is limited to up to 24 articles per team, starting September 1. Category labels are automated and can be imperfect. Earlier off-season history is not covered comprehensively. <a href="${safeLink(r.official_news)}" target="_blank" rel="noopener noreferrer">More from the team ↗</a></p></section>`;
  }
  function standings(){
    const rows=current.filter(r=>state.conference==='ALL'||r.division.startsWith(state.conference));
    let html=`<div class="page-title"><div><span class="eyebrow">THE BIGGER PICTURE</span><h1>THE <em>STANDINGS.</em></h1><p>Finals checked ${fmt(S.as_of)}. Week ${S.latest_week} is partly complete.</p></div></div><div class="chip-row conference-chips">${['ALL','AFC','NFC'].map(id=>`<button class="chip ${state.conference===id?'active':''}" data-conference="${id}" aria-pressed="${state.conference===id}">${id==='ALL'?'Both conferences':id}</button>`).join('')}</div>`;
    if(state.spoilers)return html+`<div class="protected-panel wide"><span>◉</span><h3>Standings tell you who won.</h3><p>Records, streaks and points stay hidden while outcome protection is on.</p><button class="primary-button" data-show-outcomes>Show the league picture ↗</button></div>`;
    if(state.depth==='little')html+=`<div class="explanation"><b>THE QUICK READ</b><p>W–L–T means wins, losses and ties. Teams are grouped into four-team divisions. Byes mean some have played fewer games; winning percentage accounts for that.</p></div>`;
    const divisions=[...new Set(rows.map(r=>r.division))].sort();
    html+=`<div class="division-grid">${divisions.map(div=>`<section class="division"><div class="division-title"><h2>${div}</h2><span>W–L–T</span></div>${C.sortRecords(rows.filter(r=>r.division===div)).map(r=>`<button class="standings-row ${state.team===r.id?'followed':''}" data-team-room="${r.id}">${badge(r.id)}<span class="standing-name"><b>${esc(r.short)}</b><span class="pct-bar"><i style="width:${r.pct*100}%"></i></span><small>${(r.pct*100).toFixed(1)}% win rate ${state.depth==='well'?`· ${r.pf-r.pa>0?'+':''}${r.pf-r.pa} point diff`:''}</small></span><span class="standing-record"><b>${C.record(r)}</b>${state.depth==='well'?`<small>${r.pf} PF / ${r.pa} PA</small>`:''}</span></button>`).join('')}</section>`).join('')}</div><p class="microcopy">Sorted by winning percentage, then name. This is not playoff seeding: official tiebreakers are not applied. Ties count as half a win. Full-season records ignore the catch-up date filter. <a href="https://www.nfl.com/standings/" target="_blank" rel="noopener noreferrer">Official standings ↗</a></p>`;
    return html;
  }
  const lessons=[
    ['01','THE CHAIN','Four chances. Ten yards.','An offense normally gets four downs to gain ten yards. Reach the target and the downs reset. On fourth down, teams often punt, try a field goal, or try to keep the drive alive.','Third-and-6 = third down, six yards to a new first down.'],
    ['02','THE SCORE','The numbers on the board.','A touchdown is six points, followed by a one-point kick or a two-point attempt. A field goal is three. A safety is two.','A seven-point gap can be erased by a touchdown and extra point.'],
    ['03','THE CALENDAR','17 games. 18 weeks.','Each team plays 17 regular-season games, with one week off called a bye. That is why two teams can have different numbers of games played at the same point in the season.','5–2 is seven games played. 5–3 is eight.'],
    ['04','THE RACE','The path to the playoffs.','Seven teams qualify in each conference: four division winners and three wild cards. Only the top seed gets a first-round bye.','A wild card is a qualifier that did not win its division.'],
    ['05','THE STATS','Yards aren’t points.','Total yards describe how far the offense moved the ball. Turnovers hand possession to the opponent. Possession time measures how long a team held the ball. None of these alone decides the winner.','A team can gain fewer yards and still win. The final score decides.'],
    ['06','THE CONTEXT','Know what a report says.','A trade changes the roster. A depth-chart move changes who starts. An injury report is a dated availability update. “Questionable” is not the same as definitely out.','A past game recap cannot confirm who will play next Sunday.']
  ];
  function learn(){return `<div class="page-title"><div><span class="eyebrow">A WAY INTO THE CONVERSATION</span><h1>FOOTBALL.<br><em>DECODED.</em></h1><p>Start anywhere. Ask in your own words, then follow the answer further.</p></div><div class="learn-decoration" aria-hidden="true">X <span>→</span> O</div></div>${HuddleResearch.markup(state.depth,state.spoilers)}<details class="quick-basics"><summary>Keep a few basics handy</summary><div class="learn-grid">${lessons.map(([n,k,t,p,e])=>`<article class="lesson"><div><span class="lesson-number">${n}</span><span class="eyebrow">${k}</span></div><h2>${t}</h2><p>${p}</p><div class="lesson-example">${e}</div></article>`).join('')}</div></details><p class="microcopy">Reference: <a href="https://operations.nfl.com/rules-officiating/nfl-football-basics/football-terms" target="_blank" rel="noopener noreferrer">NFL Football Operations · Football terms ↗</a></p>`;}
  function lineScore(g){
    const n=Math.max(g.away.quarters?.length||0,g.home.quarters?.length||0);if(!n)return '<p class="subtle">Quarter scores are not available in the source for this game.</p>';
    return `<div class="line-score-wrap"><table class="line-score"><caption>Points scored in each quarter</caption><thead><tr><th scope="col">TEAM</th>${Array.from({length:n},(_,i)=>`<th scope="col">${i<4?'Q'+(i+1):'OT'+(i>4?i-3:'')}</th>`).join('')}<th scope="col">FINAL</th></tr></thead><tbody>${[g.away,g.home].map(r=>`<tr><th scope="row">${r.team}</th>${Array.from({length:n},(_,i)=>`<td>${r.quarters?.[i]??'—'}</td>`).join('')}<td><strong>${r.score}</strong></td></tr>`).join('')}</tbody></table></div>`;
  }
  function scoreFlow(g){
    const pts=C.quarterFlow(g);if(!pts.length)return '';
    const W=560,H=165,p=25,max=Math.max(7,g.home.score,g.away.score),x=i=>p+i/(pts.length-1)*(W-2*p),y=n=>H-p-n/max*(H-2*p);
    return `<div class="score-flow"><div class="flow-legend"><span class="away">${g.away.team}</span><span class="home">${g.home.team}</span><small>CUMULATIVE POINTS AT QUARTER END</small></div><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Quarter-end score progression for ${esc(full(g.away.team))} and ${esc(full(g.home.team))}"><g class="chart-grid">${[0,max/2,max].map(n=>`<path d="M${p} ${y(n)}H${W-p}"/><text x="4" y="${y(n)+3}">${Math.round(n)}</text>`).join('')}</g>${['away','home'].map(side=>`<polyline class="${side}" points="${pts.map((v,i)=>`${x(i)},${y(v[side])}`).join(' ')}"/>${pts.map((v,i)=>`<circle class="${side}" cx="${x(i)}" cy="${y(v[side])}" r="3"/>`).join('')}`).join('')}<g class="chart-labels">${pts.map((v,i)=>`<text x="${x(i)}" y="${H-4}" text-anchor="middle">${i===0?'KICKOFF':i<=4?'Q'+i:'OT'}</text>`).join('')}</g></svg></div>`;
  }
  const statDefs=[['totalYards','Total yards','How far the offense moved the ball.'],['netPassingYards','Passing yards','Net yards through the air, including sack losses.'],['rushingYards','Rushing yards','Yards gained running the ball.'],['firstDowns','First downs','Times the offense earned a new set of downs.'],['thirdDownEff','Third downs','Conversions versus attempts on third down.'],['turnovers','Turnovers','Possessions lost to the opponent. Fewer is generally better.'],['possessionTime','Possession','Time with the ball.'],['yardsPerPlay','Yards per play','Average gain per offensive play.'],['fourthDownEff','Fourth downs','Conversions and attempts.'],['redZoneAttempts','Red zone','Source red-zone efficiency.'],['totalPenaltiesYards','Penalties / yards','Accepted penalties and yards.'],['sacksYardsLost','Sacks / yards lost','Times sacked and lost yardage.'],['totalOffensivePlays','Offensive plays','Total offensive snaps.'],['totalDrives','Drives','Offensive possessions.'],['fumblesLost','Fumbles lost','Fumbles recovered by the other team.'],['interceptions','Interceptions thrown','Passes caught by the defense.']];
  function statsPanel(g){
    if(!g.stats||Object.keys(g.stats).length!==2)return '<div class="empty"><p>Detailed team statistics were unavailable from the source. The verified result is shown above.</p></div>';
    const defs=state.depth==='little'?statDefs.filter(([k])=>['totalYards','turnovers','possessionTime'].includes(k)):state.depth==='basics'?statDefs.slice(0,6):statDefs;
    return `<section class="game-stat-panel"><h3>The numbers underneath.</h3><div class="stat-team-labels"><b>${g.away.team}</b><span>TEAM COMPARISON</span><b>${g.home.team}</b></div>${defs.map(([key,label,explain])=>{const a=g.stats[g.away.team]?.[key],h=g.stats[g.home.team]?.[key];if(a==null||h==null)return '';let av=parseFloat(a),hv=parseFloat(h),sum=av+hv,bar=!['thirdDownEff','possessionTime'].includes(key)&&Number.isFinite(sum)&&sum>0;return `<div class="comparison-row"><div><strong>${esc(a)}</strong><span>${label}${state.depth==='little'?`<small>${explain}</small>`:''}</span><strong>${esc(h)}</strong></div>${bar?`<div class="comparison-bar"><i style="width:${av/sum*100}%"></i><i style="width:${hv/sum*100}%"></i></div>`:''}</div>`;}).join('')}<p class="microcopy">These are box-score comparisons, not a rating of which team played better.</p></section>`;
  }
  function leadersPanel(g){
    if(!g.leaders?.length)return '';
    return `<section class="leaders-panel"><h3>Names behind the numbers.</h3><div class="leader-grid">${g.leaders.map(l=>`<article>${badge(l.team,'small')}<div><span>${esc(l.kind)}</span><b>${esc(l.name)}</b><p>${esc(l.stat)}</p></div></article>`).join('')}</div></section>`;
  }
  function deepGame(g){
    return `<section class="deep-game"><details><summary>Every scoring play <span>${g.scoring_plays?.length||0} plays</span></summary>${g.scoring_plays?.length?`<ol class="scoring-log">${g.scoring_plays.map(p=>`<li><span>Q${esc(p.quarter)} · ${esc(p.clock)}<b>${esc(p.team)}</b></span><p>${esc(p.text)}</p><strong>${p.away}–${p.home}</strong></li>`).join('')}</ol>`:'<p>Scoring-play data is unavailable for this game.</p>'}</details><details><summary>Full player box score <span>Passing to special teams</span></summary><p class="microcopy">Source categories and available player rows. Scroll tables horizontally on small screens. Hover column labels for definitions.</p>${(g.player_stats||[]).map(t=>`<section class="player-box"><h3>${esc(full(t.team))}</h3>${t.categories.filter(c=>c.players.length).map(c=>`<details><summary>${esc(c.name.replace(/([A-Z])/g,' $1'))} <span>${c.players.length} players</span></summary><div class="line-score-wrap"><table class="line-score"><caption>${esc(t.team+' '+c.name)}</caption><thead><tr><th scope="col">Player</th>${c.labels.map((l,i)=>`<th scope="col" title="${esc(c.descriptions[i]||l)}">${esc(l)}</th>`).join('')}</tr></thead><tbody>${c.players.map(p=>`<tr><th scope="row">${esc(p.name)}</th>${p.stats.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`).join('')}</section>`).join('')||'<p>Player box scores were not available from the source.</p>'}</details></section>`;
  }
  function gameDetail(g){
    const hide=g.completed&&locked(g.id),read=C.gameRead(g),ctx=C.gameContext(S,g);
    let html=`<div class="game-detail-head"><span class="eyebrow">WEEK ${String(g.week).padStart(2,'0')} / ${esc(when(g))}</span><h2 id="game-dialog-title">${esc(short(g.away.team))} <span>at</span> ${esc(short(g.home.team))}</h2><p>${esc(g.venue)}${g.neutral?' · Neutral site':''}</p></div><div class="detail-scoreboard"><div>${badge(g.away.team,'large')}<b>${esc(full(g.away.team))}</b></div><strong>${g.completed?(hide?'—':g.away.score):'VS'}<i>${g.completed?':':''}</i>${g.completed?(hide?'—':g.home.score):''}</strong><div>${badge(g.home.team,'large')}<b>${esc(full(g.home.team))}</b></div></div>`;
    if(hide)return html+`<div class="protected-panel"><span>◉</span><h3>The whole result is protected.</h3><p>Revealing this game opens its score, quarter-by-quarter story, statistics and player leaders.</p><button class="primary-button" data-reveal-game="${g.id}">Reveal this game ↗</button></div>`;
    if(g.completed){
      html+=`<div class="game-read"><span class="status-pill">${esc(read.kind)}</span><p>${esc(read.text)}</p><small>Calculated from the score and quarter totals.</small></div><div class="record-delta">${ctx.map(r=>`<span><b>${r.team}</b><small>BEFORE → AFTER</small><strong>${r.before} <i>→</i> ${r.after}</strong></span>`).join('')}</div>${lineScore(g)}${state.depth==='little'?'<div class="explanation"><b>READING THE GAME</b><p>Each quarter’s points add up to the final score. The chart shows the score at the end of each quarter, not every scoring play.</p></div>':''}${scoreFlow(g)}${statsPanel(g)}${state.depth==='well'?leadersPanel(g):`<details class="leader-details"><summary>Player leaders</summary>${leadersPanel(g)}</details>`}`;
    }else{
      html+=`<div class="upcoming-note"><span class="status-pill">STILL TO COME</span><h3>${esc(when(g))}</h3><p>${esc(g.broadcasts?.join(' / ')||'Broadcast not yet confirmed')} · Schedule checked ${fmt(S.as_of)}, 2026.</p>${!g.time_confirmed?'<p>The date and kickoff are still to be confirmed. Check the official schedule closer to game week.</p>':''}</div>`;
      if(state.spoilers)html+='<p class="protected-inline">Current team records are hidden while outcome protection is on.</p>';
      else html+=`<div class="matchup-comparison">${[g.away,g.home].map(r=>{const t=recordMap[r.team];return `<article><span>${t.id}</span><strong>${C.record(t)}</strong><p>${(t.pf/t.gp).toFixed(1)} points per game<br>${(t.pa/t.gp).toFixed(1)} allowed per game</p>${formDots(t)}</article>`;}).join('')}</div><p class="microcopy">Current season averages from completed games as of ${fmt(S.as_of)}, not a forecast of this matchup.</p>`;
    }
    if(g.completed)html+=deepGame(g);
    html+=`<div class="detail-footer"><a class="secondary-button" href="${safeLink(g.source)}" target="_blank" rel="noopener noreferrer">ESPN game page ↗</a><span>Snapshot: ${fmt(S.as_of)}, 2026. External pages may contain other results.</span></div>`;
    return html;
  }
  function openGame(id){const g=S.games.find(g=>g.id===id);if(!g)return;openedGame=id;state.game=id;persist();$('#game-detail').innerHTML=gameDetail(g);if(!$('#game-dialog').open)$('#game-dialog').showModal();}
  function closeGame(){openedGame=null;state.game=null;persist();$('#game-dialog').close();}
  function render(){
    document.documentElement.dataset.theme=state.theme;
    $('meta[name="theme-color"]').content=state.theme==='dark'?'#090d16':'#f0f2ed';
    $('#theme-toggle').textContent=state.theme==='dark'?'☾':'☀';$('#theme-toggle').setAttribute('aria-label',state.theme==='dark'?'Switch to day mode':'Switch to night mode');$('#theme-toggle').title=state.theme==='dark'?'Switch to day mode':'Switch to night mode';
    $$('.depths button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.depth===state.depth)));
    $('#level-note').textContent={little:'A little: football context, as you go.',basics:'The basics: the changes and the connections.',well:'Very well: the reporting and full available stats.'}[state.depth];
    $('#since').max=S.as_of;$('.date-stamp').textContent='DATA '+fmt(S.as_of).toUpperCase();$('.edition-tag').textContent=fmt(S.as_of).toUpperCase()+', 2026 DATA EDITION';$('#score-strip').setAttribute('aria-label','Latest completed games');const preset=[...$('#period').options].some(o=>o.value===state.since);$('#period').value=preset?state.since:'custom';$('#custom-wrap').hidden=preset;$('#since').value=state.since;$('#team').value=state.team;$('#spoilers').checked=state.spoilers;
    $$('.main-nav button').forEach(b=>{b.classList.toggle('active',b.dataset.tab===state.tab);b.setAttribute('aria-current',b.dataset.tab===state.tab?'page':'false');});
    $('#breadcrumb-view').textContent=names[state.tab];$('#coverage-line').textContent=`${fmt(state.since)} – ${fmt(S.as_of)} · 2026 edition`;
    scoreStrip();$('#view').innerHTML=({brief,games:gamesView,teams:teamRoom,league:standings,learn}[state.tab])();if(state.tab==='learn')HuddleResearch.bind();
    if(openedGame)$('#game-detail').innerHTML=gameDetail(S.games.find(g=>g.id===openedGame));
  }
  S.teams.forEach(t=>{const o=document.createElement('option');o.value=t.id;o.textContent=t.name;$('#team').append(o);});
  $('#coverage-note').textContent=D.coverage_note;
  const age=Math.floor((Date.now()-Date.parse(S.as_of+'T23:59:59-05:00'))/86400000);
  if(age>=2){$('#freshness').hidden=false;$('#freshness').textContent=`This is the ${fmt(S.as_of)} edition, now ${age} days past its date. New results and roster changes may be missing; check the linked official sources for the latest.`;}
  document.addEventListener('click',e=>{
    if(e.target.closest('[data-home]')){e.preventDefault();setState({tab:'brief'},{focus:true});return;}
    const b=e.target.closest('button');if(!b)return;
    if(b.dataset.depth){setState({depth:b.dataset.depth});notice(`${b.textContent}: context updated.`);}
    else if(b.dataset.tab){setState({tab:b.dataset.tab},{focus:true});}
    else if(b.dataset.week){setState({tab:'games',week:b.dataset.week==='all'?'all':Number(b.dataset.week),gameStatus:'all',closeGames:false},{focus:true});}
    else if(b.dataset.game)openGame(b.dataset.game);
    else if(b.hasAttribute('data-close-game'))closeGame();
    else if(b.dataset.revealGame){revealed.add(b.dataset.revealGame);render();notice('This game is now visible.');}
    else if(b.dataset.researchTeam){HuddleResearch.draft('What has changed for the '+full(b.dataset.researchTeam)+' since '+state.since+'? Explain the games, quarterback, coaching, injuries and roster moves.');setState({tab:'learn'},{focus:true});}
    else if(b.dataset.teamRoom){setState({tab:'teams',teamFocus:b.dataset.teamRoom},{focus:true});}
    else if(b.dataset.followTeam){setState({team:b.dataset.followTeam});notice(`${full(state.team)} selected for your catch up.`);}
    else if(b.dataset.topic)setState({topic:b.dataset.topic});
    else if(b.dataset.status)setState({gameStatus:b.dataset.status});
    else if(b.dataset.conference)setState({conference:b.dataset.conference});
    else if(b.dataset.reveal){revealed.add(b.dataset.reveal);render();notice('This story is now visible.');}
    else if(b.hasAttribute('data-show-outcomes')){revealed.clear();setState({spoilers:false});}
    else if(b.hasAttribute('data-all-games')||b.hasAttribute('data-clear-game-filters'))setState({tab:'games',week:'all',team:'ALL',gameStatus:'all',gameQuery:'',closeGames:false},{focus:true});
    else if(b.hasAttribute('data-window-games')){const gs=C.games(S,state),weeks=[...new Set(gs.map(g=>g.week))];setState({tab:'games',week:weeks.length===1?weeks[0]:'all',gameStatus:'final',gameQuery:'',closeGames:false},{focus:true});}
    else if(b.hasAttribute('data-reset-filters'))setState({team:'ALL',topic:'all',query:'',since:C.normalize({},S).since});
    else if(b.id==='more'){storyLimit+=6;render();}
    else if(b.id==='more-games'){gameLimit+=48;render();}
    else if(b.id==='theme-toggle')setState({theme:state.theme==='dark'?'light':'dark'},{keepLimit:true});
    else if(b.id==='reset'){revealed.clear();history.replaceState(null,'',location.pathname+location.search);state=C.normalize({},S);storyLimit=6;gameLimit=48;persist();render();notice('Reset. Night mode is the default.');}
  });
  $('#period').addEventListener('change',e=>{if(e.target.value==='custom'){$('#custom-wrap').hidden=false;$('#since').focus();}else setState({since:e.target.value});});
  $('#since').addEventListener('change',e=>{if(e.target.validity.valid&&e.target.value)setState({since:e.target.value});});
  $('#team').addEventListener('change',e=>setState({team:e.target.value}));
  $('#spoilers').addEventListener('change',e=>{revealed.clear();setState({spoilers:e.target.checked,closeGames:false});});
  $('#view').addEventListener('change',e=>{
    if(e.target.id==='order')setState({order:e.target.value});
    if(e.target.id==='team-focus')setState({teamFocus:e.target.value});
    if(e.target.id==='close-games')setState({closeGames:e.target.checked});
  });
  $('#view').addEventListener('input',e=>{
    const id=e.target.id;if(!['search','game-search'].includes(id))return;const p=e.target.selectionStart;
    setState({[id==='search'?'query':'gameQuery']:e.target.value});const input=$('#'+id);input.focus({preventScroll:true});try{input.setSelectionRange(p,p);}catch{}
  });
  $('#game-dialog').addEventListener('close',()=>{openedGame=null;state.game=null;persist();});
  $('#share').addEventListener('click',async()=>{
    const shareState={...state,spoilers:true},url=location.origin+location.pathname+'#catchup='+encodeURIComponent(JSON.stringify(shareState));
    try{await navigator.clipboard.writeText(url);notice('Link copied. Outcomes start hidden.');}catch{$('#share-url').value=url;$('#share-dialog').showModal();$('#share-url').select();}
  });
  $('#close-share').addEventListener('click',()=>$('#share-dialog').close());
  window.addEventListener('hashchange',()=>{
    if(!location.hash.startsWith('#catchup='))return;
    try{const incoming=JSON.parse(decodeURIComponent(location.hash.slice(9)));revealed.clear();if($('#game-dialog').open)closeGame();state=C.normalize({...incoming,spoilers:true},S);storyLimit=6;gameLimit=48;persist();render();if(state.game)openGame(state.game);}catch{}
  });
  render();if(linked.game&&state.game)openGame(state.game);
})();
